from fractions import Fraction as F
import json
rows=[('A',15,(1,0,0,1)),('A',9,(0,1,1,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('C',9,(1,1,1,1)),('C',5,(0,1,1,0)),('D',14,(0,0,0,0)),('D',9,(1,1,1,0))]
tests='TUVW'
cost=[F(8,10),F(12,10),F(7,10),F(14,10)]
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def stop(s):
    total=sum(rows[i][1] for i in s)
    return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in s),total),'ABCD'[a]) for a in range(4))
def best(s,available,budget):
    choices=[stop(s)]
    if budget:
        for t in available:
            choices.append((buy(s,available,budget,t),tests[t]))
    return min(choices)
def buy(s,available,budget,t):
    total=sum(rows[i][1] for i in s)
    result=cost[t]
    for bit in (0,1):
        sub=tuple(i for i in s if rows[i][2][t]==bit)
        if sub:
            result+=F(sum(rows[i][1] for i in sub),total)*best(sub,tuple(x for x in available if x!=t),budget-1)[0]
    return result
s=tuple(range(8)); avail=tuple(range(4))
values={'STOP':stop(s)[0]}
values.update({tests[t]:buy(s,avail,2,t) for t in avail})
first=min(values,key=values.get)
next_actions={}
if first!='STOP':
    t=tests.index(first)
    for bit in (0,1):
        sub=tuple(i for i in s if rows[i][2][t]==bit)
        next_actions[str(bit)]=best(sub,tuple(x for x in avail if x!=t),1)[1] if sub else 'IMPOSSIBLE'
else:
    first=stop(s)[1]
print(json.dumps({'first':first,'first_losses':{k:float(v) for k,v in values.items()},'next':next_actions}))
print('exact',values)
# Independent audit of chosen first test: sum weighted terminal losses along chosen branches.
if first=='T' and next_actions=={'0':'V','1':'W'}:
    weighted=F(0)
    for tval,second in [(0,2),(1,3)]:
        branch=[i for i in s if rows[i][2][0]==tval]
        weighted+=sum(rows[i][1] for i in branch)*cost[second]
        for val in (0,1):
            leaf=[i for i in branch if rows[i][2][second]==val]
            if leaf:
                weighted+=min(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in leaf) for a in range(4))
    audited=cost[0]+weighted/sum(r[1] for r in rows)
    assert audited==values['T']
    print('audit',audited)

