from fractions import Fraction as F
import json
# V=0 leaves the same four latent rows; a repeated display is not new evidence.
rows=[('A',15,{'T':1,'U':0,'W':1}),('B',6,{'T':1,'U':0,'W':0}),('B',5,{'T':0,'U':1,'W':0}),('D',14,{'T':0,'U':0,'W':0})]
modes='ABCD'
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
cost={'T':F(8,10),'U':F(12,10),'W':F(74,10)}
def repair(s):
    w=sum(r[1] for r in s)
    return min((F(sum(r[1]*loss[a][modes.index(r[0])] for r in s),w),modes[a]) for a in range(4))
remaining={modes[a]:F(sum(r[1]*loss[a][modes.index(r[0])] for r in rows),40) for a in range(4)}
branches={}
for t,c in cost.items():
    v=c
    branches[t]={}
    for b in (0,1):
        sub=[r for r in rows if r[2][t]==b]
        if sub:
            risk,act=repair(sub)
            v+=F(sum(r[1] for r in sub),40)*risk
            branches[t][str(b)]=act
        else:
            branches[t][str(b)]='IMPOSSIBLE'
    remaining[t]=v
action=min(remaining,key=remaining.get)
# Independently derived T policy: T=0 -> D (5*24), T=1 -> A (6*24).
assert remaining['T']==F(8,10)+F(5*24+6*24,40)==F(37,5)
assert sum(F(sum(r[1] for r in rows if r[0]==m),40) for m in modes)==1
print(json.dumps({'posterior':{m:float(F(sum(r[1] for r in rows if r[0]==m),40)) for m in modes},'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':action,'repair_after':branches.get(action,{})}))

